package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator.writeBoolean
 */
public class UTF8JsonGenerator_writeBoolean_TriageGen0Test {

    private ByteArrayOutputStream out;
    private IOContext context;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        context = IOContext.bootstrap(null);
        codec = null; // Not strictly needed for boolean writing
    }

    @Test
    public void testWriteBooleanTrue() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(context, 0, codec, out);
        gen.writeBoolean(true);
        gen.flush();

        // "true" in UTF-8 is [116, 114, 117, 101]
        byte[] expected = "true".getBytes();
        assertArrayEquals(expected, out.toByteArray());
        gen.close();
    }

    @Test
    public void testWriteBooleanFalse() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(context, 0, codec, out);
        gen.writeBoolean(false);
        gen.flush();

        // "false" in UTF-8 is [102, 97, 108, 115, 101]
        byte[] expected = "false".getBytes();
        assertArrayEquals(expected, out.toByteArray());
        gen.close();
    }

    @Test
    public void testWriteBooleanWithBufferFlush() throws IOException {
        // To trigger the (_outputTail + 5) >= _outputEnd condition, 
        // we use a very small buffer via the secondary constructor.
        // The buffer size is determined by the byte array provided.
        byte[] smallBuffer = new byte[6]; 
        // _outputTail starts at 0. 
        // If we write 'true' (len 4), _outputTail becomes 4.
        // Next write: (4 + 5) = 9. 9 >= 6 is true -> triggers _flushBuffer().

        UTF8JsonGenerator gen = new UTF8JsonGenerator(
                context, 
                0, 
                codec, 
                out, 
                smallBuffer, 
                0, 
                false
        );

        // First write: fills buffer partially
        gen.writeBoolean(true); 
        assertEquals(4, gen.getOutputBuffered());

        // Second write: triggers flush because (4 + 5) >= 6
        gen.writeBoolean(false); 

        // After flush, the 'true' should be in the 'out' stream.
        // Then 'false' is written to the fresh buffer.
        gen.flush();

        byte[] expected = "truefalse".getBytes();
        assertArrayEquals(expected, out.toByteArray());
        gen.close();
    }

    @Test
    public void testWriteBooleanLargeBuffer() throws IOException {
        // Test that it works correctly without flushing immediately in a large buffer
        byte[] largeBuffer = new byte[1024];
        UTF8JsonGenerator gen = new UTF8JsonGenerator(
                context, 
                0, 
                codec, 
                out, 
                largeBuffer, 
                0, 
                false
        );

        gen.writeBoolean(true);
        gen.writeBoolean(false);
        gen.writeBoolean(true);
        gen.flush();

        byte[] expected = "truefalsetrue".getBytes();
        assertArrayEquals(expected, out.toByteArray());
        gen.close();
    }
}
